sp_widget.client_script:
function($scope, $rootScope, $timeout) {
  var chartInstance = null;

  var dadosGraficos = $scope.data.dados || [];

  $scope.exibirGrafico = dadosGraficos.length > 0;
  $scope.exibir = $scope.exibirGrafico;

  var MESES_NOMES = ['Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago','Set','Out','Nov','Dez'];

  function inicializarGrafico(listaDados) {
    if (!listaDados || listaDados.length === 0) {
      if (chartInstance) { chartInstance.destroy(); chartInstance = null; }
      $scope.exibirGrafico = false;
      $scope.exibir = false;
      $scope.$applyAsync();
      return;
    }

    $scope.exibirGrafico = true;
    $scope.exibir = true;
    $scope.$applyAsync();

    var anosUnicos = Array.from(new Set(listaDados.map(function(it){ return it.ano; })));
    var visaoMensal = (anosUnicos.length === 1); // se veio 1 ano, mostra meses

    var labels, serieBruta, serieLiquida, tituloEixoX, sufixoRotulo;

    if (visaoMensal) {
      labels = MESES_NOMES.slice();
      tituloEixoX = 'Mês';
      sufixoRotulo = ' - Mensal';

      var bruta = new Array(12).fill(0);
      var liquida = new Array(12).fill(0);

      listaDados.forEach(function(r){
        var m = Number(r.mes);
        if (m >= 1 && m <= 12) {
          var i = m - 1;
          var v = Number(r.valor) || 0;
          if (Number(r.tipo) === 1) bruta[i]   += v; // Bruta
          if (Number(r.tipo) === 2) liquida[i] += v; // Líquida
        }
      });

      serieBruta = bruta;
      serieLiquida = liquida;

    } else {
      // visão agregada por ano (total da soma de cada ano por tipo)
      var anos = anosUnicos.sort(function(a,b){ return a - b; });
      labels = anos;
      tituloEixoX = 'Ano';
      sufixoRotulo = ' - Anual';

      var bruta = anos.map(function(){ return 0; });
      var liquida = anos.map(function(){ return 0; });

      listaDados.forEach(function(r){
        var idx = anos.indexOf(r.ano);
        if (idx > -1) {
          var v = Number(r.valor) || 0;
          if (Number(r.tipo) === 1) bruta[idx]   += v;
          if (Number(r.tipo) === 2) liquida[idx] += v;
        }
      });

      serieBruta = bruta;
      serieLiquida = liquida;
    }

    var contexto = document.getElementById('graficoDespesaPessoal').getContext('2d');

    if (chartInstance) { chartInstance.destroy(); }

    chartInstance = new Chart(contexto, {
      type: 'bar',
      data: {
        labels: labels,
        datasets: [
          {
            label: 'Despesa Bruta com Pessoal' + sufixoRotulo,
            data: serieBruta,
            backgroundColor: '#4A75B1',
            yAxisID: 'eixoEsquerdo'
          },
          {
            label: 'Despesa Líquida com Pessoal' + sufixoRotulo,
            data: serieLiquida,
            backgroundColor: '#6BB7F0',
            yAxisID: 'eixoEsquerdo'
          }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        layout: { padding: { left: 20, right: 20 } },
        scales: {
          x: { title: { display: true, text: tituloEixoX }, offset: true },
          eixoEsquerdo: {
            type: 'linear',
            position: 'left',
            beginAtZero: true,
            title: { display: true, text: 'Valores em R$' },
            ticks: {
              padding: 15,
              callback: function(value) {
                return Number(value).toLocaleString('pt-BR');
              }
            }
          }
        },
        plugins: {
          legend: { position: 'top' },
          tooltip: {
            callbacks: {
              // 2 casas decimais SOMENTE no hover
              label: function(context) {
                var v = Number(context.parsed.y) || 0;
                var s = v.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
                return context.dataset.label + ': R$ ' + s;
              }
            }
          }
        }
      }
    });
  }

  function obterDadosPorAno(ano) {
    if (!ano) {
      return dadosGraficos;
    }
    return dadosGraficos.filter(function(item) {
      return item.ano == ano;
    });
  }

  $rootScope.$on('anoSelecionado', function(evento, anoSelecionado) {
    var dadosFiltrados = obterDadosPorAno(anoSelecionado);
    inicializarGrafico(dadosFiltrados);
  });

  $timeout(function() {
    inicializarGrafico(obterDadosPorAno(null));
  }, 300);
}

sp_widget.script:
(function () {
  var gr = new GlideRecord('x_sded9_portal_t_0_despesa_bruta_e_liquida_com_pessoal');
  gr.addQuery('u_exercicio', '>=', 2019);
  gr.addQuery('u_exercicio', '<=', 2024);
  gr.orderBy('u_exercicio');
  gr.orderBy('u_mes');
  gr.query();

  var out = [];
  while (gr.next()) {
    out.push({
      ano: Number(gr.getValue('u_exercicio')),              // ex.: 2021
      mes: Number(gr.getValue('u_mes')),                    // 1..12
      tipo: Number(gr.getValue('u_tipo_de_informacao')),    // 1=Bruta, 2=Líquida
      valor: Number(gr.getValue('u_valor'))                 // valor exato
    });
  }


  // payload único e simples
  data.dados = out;
})();
